"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["79299"],{97020(e){e.exports=JSON.parse('{"id":"FIN-1329","slug":"non-fungible-token","term":"Non-Fungible Token (NFT)","also_known_as":["NFT"],"difficulty":"Advanced","definition":"A non-fungible token (NFT) is a unique digital token recorded on a blockchain that represents ownership of, or a claim to, a specific item, such as digital art, a collectible, music or a virtual item.","explanation":["Fungible assets are interchangeable: one unit of a currency is the same as any other. Non-fungible tokens are each unique, with their own identity recorded on the blockchain, which makes them suitable for representing one-of-a-kind items.","NFTs became widely known in 2021, when some digital artworks and collectibles sold for millions of dollars. They are used for digital art, trading cards, items in video games, event tickets and memberships.","For example, an artist might sell a digital artwork as an NFT, with a smart contract that automatically pays the artist a royalty each time the NFT is resold, although such royalties are not always enforced by marketplaces.","Owning an NFT usually means owning the token, not necessarily the copyright or the underlying file, which may be stored elsewhere. The NFT market has been highly volatile, with prices for many collections falling sharply after the 2021 boom. Concerns include fraud, market manipulation, unclear legal rights and the environmental impact of some blockchains."],"note":"","total":1725,"prev":{"slug":"non-disclosure-agreement","term":"Non-Disclosure Agreement (NDA)"},"next":{"slug":"non-gaap-measure","term":"Non-GAAP Measure"}}')}}]);